package android.graphics;public class Matrix{public float a=1,d=1,tx,ty;public boolean invert(Matrix o){if(a==0 || d==0)return false;o.a=1/a;o.d=1/d;o.tx=-tx/a;o.ty=-ty/d;return true;}public boolean mapRect(RectF r){float l=a*r.left+tx,rr=a*r.right+tx,t=d*r.top+ty,b=d*r.bottom+ty;r.left=Math.min(l,rr);r.right=Math.max(l,rr);r.top=Math.min(t,b);r.bottom=Math.max(t,b);return true;}}